mapper.select:
SELECT f.favorite_id as favoriteId, f.user_id as userId, f.resource_id as resourceId, f.create_time as createTime, r.title, r.description, r.uploader_name as uploaderName, r.download_count as downloadCount, r.view_count as viewCount, r.file_type as fileType, r.cover_image as coverImage, c.category_name as categoryName FROM favorite_record f LEFT JOIN resource_info r ON f.resource_id = r.resource_id LEFT JOIN resource_category c ON r.category_id = c.category_id WHERE f.user_id = #{userId} ORDER BY f.create_time DESC
LIMIT #{params.limit}
OFFSET #{params.offset}

SELECT * FROM favorite_record
WHERE user_id = #{userId} AND resource_id = #{resourceId}
LIMIT 1
